1	'use strict';
2	
3	(function setup() {
4	  const NO_REPLY = 'Could not reach the server.';
5	  const REQUEST_FAILED = 'Request failed.';
6	
7	  const form = document.getElementById('booking-form');
8	  const roomSelect = document.getElementById('room');
9	  const titleInput = document.getElementById('title');
10	  const dateInput = document.getElementById('date');
11	  const startInput = document.getElementById('start');
12	  const endInput = document.getElementById('end');
13	  const bookButton = document.getElementById('book');
14	  const filterInput = document.getElementById('filter-date');
15	  const showAllButton = document.getElementById('show-all');
16	  const list = document.getElementById('booking-list');
17	  const errorBox = document.getElementById('error');
18	
19	  let listSequence = 0;
20	
21	  function isPlainObject(value) {
22	    return typeof value === 'object' && value !== null && !Array.isArray(value);
23	  }
24	
25	  function errorMessage(body) {
26	    return isPlainObject(body) && typeof body.error === 'string' ? body.error : REQUEST_FAILED;
27	  }
28	
29	  // Resolves (never rejects) to one of:
30	  //   { kind: 'ok', body }        status === successStatus
31	  //   { kind: 'error', message }  any other status
32	  //   { kind: 'none' }            no reply, or a non-204 body that is not JSON
33	  async function request(url, options, successStatus) {
34	    let response;
35	    try {
36	      response = await fetch(url, options);
37	    } catch (failure) {
38	      return { kind: 'none' };
39	    }
40	    let body = null;
41	    if (response.status !== 204) {
42	      try {
43	        body = await response.json();
44	      } catch (failure) {
45	        return { kind: 'none' };
46	      }
47	    }
48	    if (response.status === successStatus) {
49	      return { kind: 'ok', body };
50	    }
51	    return { kind: 'error', message: errorMessage(body) };
52	  }
53	
54	  function showError(text) {
55	    errorBox.textContent = text;
56	  }
57	
58	  function showFailure(outcome) {
59	    showError(outcome.kind === 'error' ? outcome.message : NO_REPLY);
60	  }
61	
62	  function makeOption(name) {
63	    const option = document.createElement('option');
64	    option.value = name;
65	    option.textContent = name;
66	    return option;
67	  }
68	
69	  async function loadRooms() {
70	    const outcome = await request('/api/rooms', { method: 'GET' }, 200);
71	    if (outcome.kind !== 'ok') {
72	      showFailure(outcome);
73	      return;
74	    }
75	    const rooms = isPlainObject(outcome.body) ? outcome.body.rooms : null;
76	    if (!Array.isArray(rooms)) {
77	      showError(REQUEST_FAILED);
78	      return;
79	    }
80	    roomSelect.replaceChildren(...rooms.map((name) => makeOption(String(name))));
81	  }
82	
83	  function makeBookingItem(booking) {
84	    const item = document.createElement('li');
85	    const cancel = document.createElement('button');
86	    cancel.type = 'button';
87	    cancel.textContent = 'Cancel';
88	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
89	    const text = `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
90	    item.append(text, cancel);
91	    return item;
92	  }
93	
94	  function makeEmptyItem() {
95	    const item = document.createElement('li');
96	    item.append('No bookings.');
97	    return item;
98	  }
99	
100	  function renderBookings(bookings) {
101	    if (bookings.length === 0) {
102	      list.replaceChildren(makeEmptyItem());
103	      return;
104	    }
105	    list.replaceChildren(...bookings.map(makeBookingItem));
106	  }
107	
108	  function listUrl() {
109	    const date = filterInput.value;
110	    return date === '' ? '/api/bookings' : `/api/bookings?date=${date}`;
111	  }
112	
113	  async function loadList() {
114	    listSequence += 1;
115	    const sequence = listSequence;
116	    const outcome = await request(listUrl(), { method: 'GET' }, 200);
117	    if (sequence !== listSequence) {
118	      return;
119	    }
120	    if (outcome.kind !== 'ok') {
121	      showFailure(outcome);
122	      return;
123	    }
124	    const bookings = isPlainObject(outcome.body) ? outcome.body.bookings : null;
125	    if (!Array.isArray(bookings) || !bookings.every(isPlainObject)) {
126	      showError(REQUEST_FAILED);
127	      return;
128	    }
129	    renderBookings(bookings);
130	  }
131	
132	  function bookingPayload() {
133	    return JSON.stringify({
134	      room: roomSelect.value,
135	      title: titleInput.value,
136	      date: dateInput.value,
137	      start: startInput.value,
138	      end: endInput.value,
139	    });
140	  }
141	
142	  async function submitBooking(event) {
143	    event.preventDefault();
144	    if (bookButton.disabled) {
145	      return;
146	    }
147	    bookButton.disabled = true;
148	    const outcome = await request('/api/bookings', {
149	      method: 'POST',
150	      headers: { 'Content-Type': 'application/json' },
151	      body: bookingPayload(),
152	    }, 201);
153	    bookButton.disabled = false;
154	    if (outcome.kind !== 'ok') {
155	      showFailure(outcome);
156	      return;
157	    }
158	    titleInput.value = '';
159	    showError('');
160	    loadList();
161	  }
162	
163	  async function cancelBooking(id, button) {
164	    if (button.disabled) {
165	      return;
166	    }
167	    button.disabled = true;
168	    const outcome = await request(`/api/bookings/${id}`, { method: 'DELETE' }, 204);
169	    button.disabled = false;
170	    if (outcome.kind === 'none') {
171	      showError(NO_REPLY);
172	      return;
173	    }
174	    showError(outcome.kind === 'ok' ? '' : outcome.message);
175	    loadList();
176	  }
177	
178	  function showAll() {
179	    filterInput.value = '';
180	    loadList();
181	  }
182	
183	  form.addEventListener('submit', submitBooking);
184	  filterInput.addEventListener('change', loadList);
185	  showAllButton.addEventListener('click', showAll);
186	
187	  loadRooms();
188	  loadList();
189	})();
